class EventNotification(TypedDict):
    """An event plus the subscription it's for: the event's own `event` and `data` fields, and `subscription`."""
    event: str
    data: dict[str, Any]
    subscription: int


class EventsEventNotification(TypedDict):
    """One event. `event` and `data` are exactly the event's own fields."""
    method: Literal["events.event"]
    params: EventNotification


class LaggedNotification(TypedDict):
    dropped: int
    subscription: int


class EventsLaggedNotification(TypedDict):
    """The subscriber fell behind and `dropped` events were skipped just
    before the next one it receives.
    """
    method: Literal["events.lagged"]
    params: LaggedNotification


Notification = Union[
    EventsEventNotification,
    EventsLaggedNotification,
]
# A message the server sends without being asked, on a connection with a
# subscription. On the wire it's a JSON-RPC notification: `method` plus
# `params`.


ErrorCode = Literal["method_not_found", "invalid_params", "internal"] | Literal["parse_error"] | Literal["invalid_request"] | Literal["not_found"] | Literal["invalid_state"] | Literal["unsupported"] | Literal["unavailable"]


class Error(TypedDict):
    """A failed command."""
    code: ErrorCode
    data: NotRequired[Any]
    # For programs: what the error is about, such as `{"tile": "tile_…",
    # "direction": "right"}` or `{"param": "kind"}`. Over JSON-RPC these
    # fields sit in the error's `data` beside `code`.
    # 
    # `reason` narrows an `invalid_state` down for programs that act on
    # it: `no_neighbour` (no tile that way, for focus and swap) and
    # `no_edge` (no divider that way to move). Shells stay silent on both
    # when a key asked, since there's simply nothing there.
    message: str
    # For people: shells show it as is, so it names no IDs.


OnExit = Literal["close", "keep"]
# What happens to a terminal tile when the process in its pane exits
# (`exit`, ctrl+d, a finished command). Config `[terminal] on_exit`; a tile
# can override it (layout files' `on_exit`).


class TerminalTileContent(TypedDict):
    command: NotRequired[list[str] | None]
    # Command typed into the pane's shell once it starts. One element is
    # sent as a shell line (`npm run dev`); more are an argv, quoted for
    # the shell. herdr has no way to replace the shell, so the shell stays
    # when the command exits.
    cwd: NotRequired[str | None]
    # Working directory for a new pane.
    ended: NotRequired[bool]
    # The herdr pane is gone (its process exited with `on_exit = "keep"`,
    # or it was lost with its server). The shell offers Respawn or Close;
    # binding a new pane clears it.
    env: NotRequired[dict[str, Any]]
    # Extra environment for a new pane, on top of `AZULEJO_*`.
    herdr: NotRequired[HerdrRef | None]
    # Set once the herdr adapter has created or adopted a pane.
    kind: Literal["terminal"]
    on_exit: NotRequired[OnExit | None]
    # Overrides `[terminal] on_exit` for this tile.


TileContent = Union[
    TerminalTileContent,
]
# A tile's content and its kind-specific state.


FilesOpenTarget = Literal["editor", "terminal", "editor_folder"]
# Where `files.open` shows a path.


TransferMode = Literal["copy", "move"]
# What `files.transfer` does with the originals.


FileKind = Literal["file", "folder"]
# What `files.create` makes.


Direction = Literal["left", "right", "up", "down"]
# A direction on screen.


ReadSource = Literal["visible", "recent", "recent_unwrapped"]
# What `terminal.read` returns.


ApplyMode = Literal["new_workspace", "new_tab", "replace_tab"]
# Where `layout.apply` puts a layout file's tabs.



class Methods:
    """One method per API method. Subclasses provide `_call`."""

    def _call(self, method: str, params: dict[str, Any]) -> Any:
        raise NotImplementedError

    def core_ping(self) -> Reply:
        """`core.ping`. Liveness check; replies `pong`."""
        return self._call("core.ping", {})

    def session_get(self) -> Reply:
        """`session.get`. The whole object model; replies `session`."""
        return self._call("session.get", {})

    def window_create(self, *, cwd: str | None = None, workspace_name: str | None = None) -> Reply:
        """`window.create`. Opens a window with one empty workspace.

        workspace_name: Name of the window's first workspace.
        """
        return self._call("window.create", {"cwd": cwd, "workspace_name": workspace_name})

    def window_close(self, window: WindowId) -> Reply:
        """`window.close`. Closes a window and its workspaces, herdr workspaces included (see
        `workspace.close`).
        """
        return self._call("window.close", {"window": window})

    def window_focus(self, window: WindowId) -> Reply:
        """`window.focus`."""
        return self._call("window.focus", {"window": window})

    def window_set_frame(self, frame: Frame, window: WindowId) -> Reply:
        """`window.set_frame`. Records a window's frame after the user moves or resizes it."""
        return self._call("window.set_frame", {"frame": frame, "window": window})

    def window_set_sidebar(self, visible: bool, window: WindowId) -> Reply:
        """`window.set_sidebar`. Opens a window's workspace sidebar, or collapses it to a rail or out
        of sight, as `[sidebar] collapsed` says (restored on relaunch).

        visible: `true` opens the full sidebar; `false` collapses it (`[sidebar] collapsed`: a rail by default, or hidden).
        """
        return self._call("window.set_sidebar", {"visible": visible, "window": window})

    def window_list(self) -> Reply:
        """`window.list`. Every window; replies `windows`."""
        return self._call("window.list", {})

    def workspace_list(self, *, window: WindowId | None = None) -> Reply:
        """`workspace.list`. Workspaces of one window, or of all windows; replies `workspaces`.

        window: Only this window's workspaces; all when absent.
        """
        return self._call("workspace.list", {"window": window})

    def workspace_create(self, *, cwd: str | None = None, machine: str | None = None, name: str | None = None, window: WindowId | None = None) -> Reply:
        """`workspace.create`.

        machine: The herdr machine its terminals run on: `"local"` (the default), or a machine's ID or label from `machines.list`.
        window: Defaults to the focused window.
        """
        return self._call("workspace.create", {"cwd": cwd, "machine": machine, "name": name, "window": window})

    def workspace_close(self, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.close`. Closes a workspace and its tabs, and its herdr workspace with every
        tab and pane in it: their processes end. Closing a
        window's last workspace closes the window.

        workspace: Defaults to the focused workspace.
        """
        return self._call("workspace.close", {"workspace": workspace})

    def workspace_focus(self, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.focus`.

        workspace: Defaults to the focused workspace.
        """
        return self._call("workspace.focus", {"workspace": workspace})

    def workspace_rename(self, name: str, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.rename`. Renames a workspace, and its herdr workspace too."""
        return self._call("workspace.rename", {"name": name, "workspace": workspace})

    def workspace_set_repo(self, *, path: str | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.set_repo`. Sets the folder whose git branch the sidebar shows; without `path` the
        core follows the focused terminal's working directory again.

        path: A folder inside the repository; absent or empty follows the focused terminal again.
        workspace: Defaults to the focused workspace.
        """
        return self._call("workspace.set_repo", {"path": path, "workspace": workspace})

    def workspace_move(self, index: int, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.move`. Moves a workspace to another place in its window's list: the sidebar
        order, which ⌘1…⌘8 and ⌘9 (the last) follow. Saved with the session.
        It's Azulejo's own order: herdr's workspace order stays as it is.

        index: New position within its window, from 0, counted once the workspace has left its old place; past the end means last. A workspace stays in its machine's group (the window's list is grouped by machine, as the sidebar shows it), so a place past the group's edge stops there.
        """
        return self._call("workspace.move", {"index": index, "workspace": workspace})

    def workspace_bind(self, herdr_workspace: str, workspace: WorkspaceId) -> Reply:
        """`workspace.bind`. Records the herdr workspace backing a workspace. Sent by the herdr adapter."""
        return self._call("workspace.bind", {"herdr_workspace": herdr_workspace, "workspace": workspace})

    def tab_list(self, *, workspace: WorkspaceId | None = None) -> Reply:
        """`tab.list`. Tabs of one workspace, or of all workspaces; replies `tabs`.

        workspace: Only this workspace's tabs; all when absent.
        """
        return self._call("tab.list", {"workspace": workspace})

    def tab_create(self, *, content: TileContent | None = None, name: str | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`tab.create`. Opens a tab with one tile (a terminal unless `content` says otherwise).

        content: The tab's first tile; defaults to a terminal.
        workspace: Defaults to the focused workspace.
        """
        return self._call("tab.create", {"content": content, "name": name, "workspace": workspace})

    def tab_close(self, *, tab: TabId | None = None) -> Reply:
        """`tab.close`. Closes a tab and its tiles; terminals detach, as with `tile.close`.

        tab: Defaults to the focused tab.
        """
        return self._call("tab.close", {"tab": tab})

    def tab_focus(self, *, tab: TabId | None = None) -> Reply:
        """`tab.focus`.

        tab: Defaults to the focused tab.
        """
        return self._call("tab.focus", {"tab": tab})

    def tab_rename(self, *, name: str | None = None, tab: TabId | None = None) -> Reply:
        """`tab.rename`.

        name: `null` or absent clears the name.
        """
        return self._call("tab.rename", {"name": name, "tab": tab})

    def tab_move(self, index: int, *, tab: TabId | None = None) -> Reply:
        """`tab.move`.

        index: New position within its workspace; past the end means last.
        """
        return self._call("tab.move", {"index": index, "tab": tab})

    def tile_list(self, *, workspace: WorkspaceId | None = None) -> Reply:
        """`tile.list`. Lists tiles; replies `tiles`.

        workspace: Only tiles in this workspace; all tiles when absent.
        """
        return self._call("tile.list", {"workspace": workspace})

    def tile_get(self, *, tile: TileId | None = None) -> Reply:
        """`tile.get`. One tile; replies `tile`.

        tile: Defaults to the focused tile.
        """
        return self._call("tile.get", {"tile": tile})

    def tile_close(self, *, kill: bool | None = None, tile: TileId | None = None) -> Reply:
        """`tile.close`. Closes a tile. A terminal's herdr pane is detached, not killed, unless
        `kill` is set.

        kill: Kill the terminal's herdr pane instead of detaching from it.
        """
        return self._call("tile.close", {"kill": kill, "tile": tile})

    def tile_focus(self, *, tile: TileId | None = None) -> Reply:
        """`tile.focus`. Focuses a tile. Focus alone doesn't count as reading its agent's
        result: that's `tile.seen`.

        tile: Defaults to the focused tile.
        """
        return self._call("tile.focus", {"tile": tile})

    def tile_seen(self, *, tile: TileId | None = None) -> Reply:
        """`tile.seen`. The user has read the tile's agent's result: clears a finished
        agent's attention (the done mark) and an unread mark
        (`tile.mark_unread`) without moving focus. A blocked
        agent keeps its attention until its state changes. The macOS shell
        sends it once the tile has been focused, on screen, in the key window
        for 0.75 s.

        tile: Defaults to the focused tile.
        """
        return self._call("tile.seen", {"tile": tile})

    def tile_mark_unread(self, *, tile: TileId | None = None) -> Reply:
        """`tile.mark_unread`. The user wants to come back to the tile: marks its agent unread, so
        the tile shows the done mark (and counts as unread everywhere) until
        `tile.seen`, whatever the agent does in between. Tiles without an
        agent can't be marked (`invalid_state`).

        tile: Defaults to the focused tile.
        """
        return self._call("tile.mark_unread", {"tile": tile})

    def tile_rename(self, *, tile: TileId | None = None, title: str | None = None) -> Reply:
        """`tile.rename`. Sets or clears a tile's title.

        title: `null` or absent clears the title.
        """
        return self._call("tile.rename", {"tile": tile, "title": title})

    def files_list(self, *, dir: str | None = None, tile: TileId | None = None) -> Reply:
        """`files.list`. Lists one folder of a files panel (its root when `dir` is absent);
        replies `files`. Doesn't watch it: see `files.expand`.

        dir: Absolute, or relative to the panel's root; the root when absent.
        tile: The panel's id (`files.panel`).
        """
        return self._call("files.list", {"dir": dir, "tile": tile})

    def files_expand(self, *, dir: str | None = None, tile: TileId | None = None) -> Reply:
        """`files.expand`. Lists a folder and watches it from now on: changes arrive as
        `files.changed`. Shells send it when the user opens a folder.

        dir: Absolute, or relative to the panel's root; the root when absent.
        tile: The panel's id (`files.panel`).
        """
        return self._call("files.expand", {"dir": dir, "tile": tile})

    def files_collapse(self, *, dir: str | None = None, tile: TileId | None = None) -> Reply:
        """`files.collapse`. Stops watching a folder and the folders open below it.

        dir: Absolute, or relative to the panel's root; the root when absent.
        tile: The panel's id (`files.panel`).
        """
        return self._call("files.collapse", {"dir": dir, "tile": tile})

    def files_reveal(self, path: str, *, tile: TileId | None = None) -> Reply:
        """`files.reveal`. Opens the folders down to `path` and asks shells to select it
        (`files.revealed`).

        path: A file or folder under the panel's root: absolute, or relative to the panel's root.
        """
        return self._call("files.reveal", {"path": path, "tile": tile})

    def files_toggle_hidden(self, *, show: bool | None = None, tile: TileId | None = None) -> Reply:
        """`files.toggle_hidden`. Shows or hides hidden and gitignored entries; toggles when `show` is
        absent. Shells list their open folders again on `files.changed`.

        show: Show (true) or hide (false) hidden and ignored entries; toggles when absent.
        """
        return self._call("files.toggle_hidden", {"show": show, "tile": tile})

    def files_open(self, path: str, *, target: FilesOpenTarget | None = None, tile: TileId | None = None) -> Reply:
        """`files.open`. Opens a path from a files panel beside the focused tile: a file in
        the editor (a new terminal running it, to the right) or a folder in a
        new terminal below; replies `created` with the tile.

        path: Absolute, or relative to the panel's root.
        tile: The files panel (`files.panel`) the path comes from: the path opens beside the focused tile. Any tile works as the anchor instead when `path` is absolute; the focused tile when absent.
        """
        return self._call("files.open", {"path": path, "target": target, "tile": tile})

    def files_panel(self, root: str, *, machine: str | None = None, panel: TileId | None = None) -> Reply:
        """`files.panel`. Opens a files panel on `root` (or points an existing one there);
        replies `created` with the panel's id as `tile`. Panels live outside
        the session and aren't saved; shells open them again after a relaunch.

        machine: A herdr machine's ID (`machines.list`) whose files to show; Local when absent or `local`.
        panel: The panel to point at `root`; a new panel when absent.
        root: The folder to show; `~` expands to the home folder. On a remote machine, an absolute path there.
        """
        return self._call("files.panel", {"machine": machine, "panel": panel, "root": root})

    def files_panel_close(self, panel: TileId) -> Reply:
        """`files.panel_close`. Closes a files panel and stops watching its folders."""
        return self._call("files.panel_close", {"panel": panel})

    def files_transfer(self, folder: str, sources: list[str], *, from_: str | None = None, mode: TransferMode | None = None, to: str | None = None) -> Reply:
        """`files.transfer`. Moves or copies files and folders into a folder, on this machine or
        between Local and a herdr machine (`scp`); replies `transferred`
        when it's done, with what became of each.

        folder: The folder they go into: absolute, on `to`.
        from_: The machine the sources are on (`machines.list` ID); Local when absent or `local`.
        sources: Absolute paths of the files and folders, on `from`.
        to: The machine the folder is on; Local when absent or `local`.
        """
        return self._call("files.transfer", {"folder": folder, "from": from_, "mode": mode, "sources": sources, "to": to})

    def files_create(self, path: str, *, kind: FileKind | None = None, machine: str | None = None, tile: TileId | None = None) -> Reply:
        """`files.create`. Makes an empty file or folder, never replacing anything; replies
        `file_created` with its path.

        machine: The machine to make it on (`machines.list` ID); Local when absent or `local`. Leave it out with `tile`: a panel's entries are on its own machine.
        path: The new entry: absolute, or relative to the panel's root. Its last part is the name (not `.` or `..`).
        tile: A files panel (`files.panel`): `path` may be relative to its root, and a remote panel's entry is made on its machine.
        """
        return self._call("files.create", {"kind": kind, "machine": machine, "path": path, "tile": tile})

    def files_delete(self, paths: list[str], *, machine: str | None = None, tile: TileId | None = None) -> Reply:
        """`files.delete`. Deletes files and folders: to the Trash on Local, for good on a
        herdr machine; replies `deleted` with what became of each.

        machine: The machine the paths are on (`machines.list` ID); Local when absent or `local`. Leave it out with `tile`: a panel's entries are on its own machine.
        paths: Absolute, or relative to the panel's root.
        tile: A files panel (`files.panel`): paths may be relative to its root, and a remote panel's are on its machine.
        """
        return self._call("files.delete", {"machine": machine, "paths": paths, "tile": tile})

    def files_ssh_url(self, path: str, *, machine: str | None = None, tile: TileId | None = None) -> Reply:
        """`files.ssh_url`. A path on a herdr machine as an `ssh://` URL for apps with their
        own SSH; replies `ssh_url`.

        machine: The machine the path is on (`machines.list` ID). Leave it out with `tile`: a panel's entries are on its own machine.
        path: Absolute, or relative to the panel's root.
        tile: A files panel (`files.panel`): `path` may be relative to its root, and a remote panel's paths are on its machine.
        """
        return self._call("files.ssh_url", {"machine": machine, "path": path, "tile": tile})

    def layout_get(self) -> Reply:
        """`layout.get`. The focused tab's layout; emits `layout.changed` and replies `layout`."""
        return self._call("layout.get", {})

    def layout_split(self, direction: Direction, *, content: TileContent | None = None, tile: TileId | None = None) -> Reply:
        """`layout.split`. Splits a tile and opens a new one beside it, which takes focus.

        content: The new tile; defaults to a terminal.
        direction: Which side of `tile` the new tile goes.
        tile: The tile to split; defaults to the focused one.
        """
        return self._call("layout.split", {"content": content, "direction": direction, "tile": tile})

    def layout_focus(self, direction: Direction) -> Reply:
        """`layout.focus`. Moves focus to the neighbouring tile."""
        return self._call("layout.focus", {"direction": direction})

    def layout_swap(self, *, direction: Direction | None = None, tile: TileId | None = None, with_: TileId | None = None) -> Reply:
        """`layout.swap`. Swaps a tile with its neighbour in `direction`, or with tile `with`.

        direction: Swap with the neighbour this way. Give exactly one of `direction`, `with`.
        with_: Swap with this tile, which must be in the same tab.
        """
        return self._call("layout.swap", {"direction": direction, "tile": tile, "with": with_})

    def layout_move(self, direction: Direction, *, tile: TileId | None = None) -> Reply:
        """`layout.move`. Moves a tile one step: into its neighbour's slot, or to the tab's edge."""
        return self._call("layout.move", {"direction": direction, "tile": tile})

    def layout_resize(self, direction: Direction, *, amount: float | None = None, tile: TileId | None = None) -> Reply:
        """`layout.resize`. Moves a tile's edge in `direction` by `amount` (negative shrinks).

        amount: Share of the enclosing split to move the edge by. Defaults to `[layout] resize_step` (0.04 unless the config changes it).
        """
        return self._call("layout.resize", {"amount": amount, "direction": direction, "tile": tile})

    def layout_zoom(self, *, tile: TileId | None = None, zoomed: bool | None = None) -> Reply:
        """`layout.zoom`. Zooms a tile to fill its tab; leave `zoomed` out to toggle.

        zoomed: `true` zooms, `false` unzooms, absent toggles.
        """
        return self._call("layout.zoom", {"tile": tile, "zoomed": zoomed})

    def layout_split_auto(self, *, content: TileContent | None = None, tab: TabId | None = None) -> Reply:
        """`layout.split_auto`. Opens a tile at the end of the tab's stack, whichever tile has focus; a
        lone tile becomes master | stack. In a manual tab the stack is evened
        out afterwards; in a dynamic tab the tile goes where `[layout] insert`
        says.

        content: The new tile; defaults to a terminal.
        tab: Defaults to the focused tab.
        """
        return self._call("layout.split_auto", {"content": content, "tab": tab})

    def layout_promote(self, *, tile: TileId | None = None) -> Reply:
        """`layout.promote`. Swaps a tile with its tab's master (manual tab) or moves it to the
        front of the order (dynamic tab); focus stays on the tile.

        tile: Defaults to the focused tile.
        """
        return self._call("layout.promote", {"tile": tile})

    def layout_rotate(self, *, flip: bool | None = None, part: bool | None = None, reverse: bool | None = None, tab: TabId | None = None) -> Reply:
        """`layout.rotate`. Turns a Tile tab a quarter turn, as Bismuth's rotate: the master area
        goes left → top → right → bottom (clockwise), or back with `reverse`.
        `part` turns only the master area instead ("rotate part": masters
        side by side or stacked), and `flip` toggles master left ↔ top
        (`tall.py`'s rotate). A manual tab turns its whole split tree a
        quarter turn, whatever its shape (`reverse` turns it back; `flip`
        still toggles master left ↔ top). Monocle and Three Column have
        nothing to turn: the command succeeds and changes nothing.

        flip: Toggle master left ↔ top (and right ↔ bottom in a Tile tab) instead of turning; a manual tree is rebuilt in tall shape. Not with `part`.
        part: Tile tabs: turn only the master area, so several masters sit side by side instead of stacked.
        reverse: Turn anticlockwise: a Tile tab's master goes left → bottom → right → top; a manual tab's tree turns back the other way.
        tab: Defaults to the focused tab.
        """
        return self._call("layout.rotate", {"flip": flip, "part": part, "reverse": reverse, "tab": tab})

    def layout_equalize(self, *, tab: TabId | None = None) -> Reply:
        """`layout.equalize`. Gives every tile in the tab's stack the same size.

        tab: Defaults to the focused tab.
        """
        return self._call("layout.equalize", {"tab": tab})

    def layout_set(self, kind: LayoutKind, *, tab: TabId | None = None) -> Reply:
        """`layout.set`. Switches a tab to a layout kind: `manual` or a dynamic one.

        tab: Defaults to the focused tab.
        """
        return self._call("layout.set", {"kind": kind, "tab": tab})

    def layout_toggle(self, kind: LayoutKind, *, tab: TabId | None = None) -> Reply:
        """`layout.toggle`. Switches a tab to `kind`, or back to its previous kind if `kind` is
        already active.

        tab: Defaults to the focused tab.
        """
        return self._call("layout.toggle", {"kind": kind, "tab": tab})

    def layout_cycle(self, *, step: int | None = None, tab: TabId | None = None) -> Reply:
        """`layout.cycle`. Steps through the configured cycle of layout kinds.

        step: Positions to move through the cycle; negative goes back. Defaults to 1.
        tab: Defaults to the focused tab.
        """
        return self._call("layout.cycle", {"step": step, "tab": tab})

    def layout_masters(self, *, delta: int | None = None, tab: TabId | None = None) -> Reply:
        """`layout.masters`. Adds (or with a negative `delta` removes) masters in a Tile or Three
        Column tab.

        delta: How many masters to add; negative removes. Defaults to 1.
        tab: Defaults to the focused tab.
        """
        return self._call("layout.masters", {"delta": delta, "tab": tab})

    def layout_master_ratio(self, *, delta: float | None = None, tab: TabId | None = None) -> Reply:
        """`layout.master_ratio`. Grows (positive `delta`) or shrinks the master area of a Tile or Three
        Column tab.

        delta: Change in the master area's share; negative shrinks. Defaults to `[layout] resize_step` (0.04 unless the config changes it).
        tab: Defaults to the focused tab.
        """
        return self._call("layout.master_ratio", {"delta": delta, "tab": tab})

    def layout_move_order(self, *, step: int | None = None, tile: TileId | None = None) -> Reply:
        """`layout.move_order`. Moves a tile `step` places along its dynamic tab's order, wrapping.

        step: Places to move; negative moves towards the front. Defaults to 1.
        tile: Defaults to the focused tile.
        """
        return self._call("layout.move_order", {"step": step, "tile": tile})

    def layout_set_ratio(self, *, path: str | None = None, ratio: float | None = None, tab: TabId | None = None) -> Reply:
        """`layout.set_ratio`. Moves the divider of one split in a tab's tree, as dragging it does:
        its `a` side gets `ratio` of the split, or leave `ratio` out to even
        it out. A manual tab sets that split's ratio (what's nested keeps its
        proportions). A Tile or Three Column tab turns it into its
        parameters: the master ratio, Three Column's ratio (the centre stays
        centred, so both side columns follow), or the sizes of the two tiles
        either side of the divider. Monocle has no dividers.

        path: The split, as steps from the root of the tab's tree (`root` in `session.get` and `layout.changed`): `a` for a split's first child, `b` for its second. `""` (the default) is the root; `"ba"` is the first child of the root's second child.
        ratio: The share of the split given to its `a` side, clamped to what the layout allows (5–95 % per split; Tile's master area 20–80 %). Leave it out to even the split out.
        tab: Defaults to the focused tab.
        """
        return self._call("layout.set_ratio", {"path": path, "ratio": ratio, "tab": tab})

    def terminal_bind(self, herdr: HerdrRef, tile: TileId) -> Reply:
        """`terminal.bind`. Records the herdr pane a terminal tile views. Sent by the herdr adapter."""
        return self._call("terminal.bind", {"herdr": herdr, "tile": tile})

    def terminal_respawn(self, *, tile: TileId | None = None) -> Reply:
        """`terminal.respawn`. Gives an ended terminal tile a fresh herdr pane, keeping the tile's id
        and place. The new pane gets its own herdr tab and the tile's cwd.

        tile: Defaults to the focused tile.
        """
        return self._call("terminal.respawn", {"tile": tile})

    def terminal_send_text(self, text: str, *, tile: TileId | None = None) -> Reply:
        """`terminal.send_text`.

        text: Sent literally, as if pasted.
        """
        return self._call("terminal.send_text", {"text": text, "tile": tile})

    def terminal_send_keys(self, keys: list[str], *, tile: TileId | None = None) -> Reply:
        """`terminal.send_keys`.

        keys: Key names in herdr's notation, e.g. `enter`, `ctrl+c`, `up`.
        """
        return self._call("terminal.send_keys", {"keys": keys, "tile": tile})

    def terminal_read(self, *, lines: int | None = None, source: ReadSource | None = None, tile: TileId | None = None) -> Reply:
        """`terminal.read`. Reads a terminal's screen or history; replies `text`. History lives in
        herdr, not in the tile.

        lines: Upper bound on lines returned.
        """
        return self._call("terminal.read", {"lines": lines, "source": source, "tile": tile})

    def terminal_scroll(self, offset_from_bottom: int, *, tile: TileId | None = None) -> Reply:
        """`terminal.scroll`. Scrolls a terminal's view; replies `scroll`. 0 is the live bottom.

        offset_from_bottom: Lines above the live bottom; 0 returns to it.
        """
        return self._call("terminal.scroll", {"offset_from_bottom": offset_from_bottom, "tile": tile})

    def terminal_search(self, query: str, *, case_sensitive: bool | None = None, lines: int | None = None, locate: bool | None = None, tile: TileId | None = None) -> Reply:
        """`terminal.search`. Finds lines containing `query` in a terminal's history; replies
        `matches`. Runs over `recent_unwrapped` output in the core.

        lines: How many lines of history to search; herdr's default when absent, or all of it with `locate`.
        locate: Also work out where each match sits in herdr's buffer (`row`) and the `terminal.scroll` offset that shows it mid-view, as a find bar needs. Costs two more herdr calls.
        query: Literal text to find.
        """
        return self._call("terminal.search", {"case_sensitive": case_sensitive, "lines": lines, "locate": locate, "query": query, "tile": tile})

    def events_subscribe(self, *, filter: list[str] | None = None, tile: TileId | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`events.subscribe`. Streams events on this connection as `events.event` notifications;
        replies `subscribed`. Answered by the API server, not the engine.

        filter: Event names or prefixes. `tile.created` matches that event only; `tile.`, `tile.*` and `tile` match every `tile.…` event. Empty or absent means every event.
        tile: Only events about this tile: its own `tile.*` and `agent.state_changed` events, layout changes of its tab, and focus changes to or from it.
        workspace: Only events about this workspace: its own events, its tabs' and its tiles', and `focus.changed` when focus lands in it. Events about no particular workspace (`herdr.status`, window events) are left out.
        """
        return self._call("events.subscribe", {"filter": filter, "tile": tile, "workspace": workspace})

    def events_unsubscribe(self, subscription: int) -> Reply:
        """`events.unsubscribe`. Ends a subscription made on this connection.

        subscription: The `subscription` from `events.subscribe`'s reply.
        """
        return self._call("events.unsubscribe", {"subscription": subscription})

    def layout_apply(self, *, base_dir: str | None = None, mode: ApplyMode | None = None, path: str | None = None, toml: str | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`layout.apply`. Opens a project layout file's tabs and tiles; replies `created` with
        the workspace and first tab.

        base_dir: What relative `cwd` and `path` values in the file resolve against. Defaults to the file's directory, or the workspace's cwd for `toml`.
        path: A layout file (`.azulejo.toml`). Give exactly one of `path` and `toml`.
        toml: The layout file's text.
        workspace: For `new_tab` and `replace_tab`; the focused workspace by default.
        """
        return self._call("layout.apply", {"base_dir": base_dir, "mode": mode, "path": path, "toml": toml, "workspace": workspace})

    def layout_export(self, *, path: str | None = None, tab: TabId | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`layout.export`. A tab or workspace as layout-file TOML; replies `layout_file`.

        path: Also write the file here. Paths in it are made relative to its directory where they're inside it.
        tab: Export one tab. Without it, the whole workspace.
        workspace: The workspace to export; the focused one by default.
        """
        return self._call("layout.export", {"path": path, "tab": tab, "workspace": workspace})

    def commands_list(self) -> Reply:
        """`commands.list`. Every action the palette offers, with its current key chords;
        replies `commands`.
        """
        return self._call("commands.list", {})

    def config_keys(self) -> Reply:
        """`config.keys`. Every keymap action with its context, default and current chords, and
        whether the user's config set it; replies `keys`.
        """
        return self._call("config.keys", {})

    def config_defaults(self) -> Reply:
        """`config.defaults`. A commented `[keys]` template with every action and its default
        chords, ready to paste into the config file; replies `text`.
        """
        return self._call("config.defaults", {})

    def machines_list(self) -> Reply:
        """`machines.list`. Local plus herdr's saved machines and their connection state;
        replies `machines`.
        """
        return self._call("machines.list", {})


class AsyncMethods:
    """One coroutine per API method. Subclasses provide `_call`."""

    async def _call(self, method: str, params: dict[str, Any]) -> Any:
        raise NotImplementedError

    async def core_ping(self) -> Reply:
        """`core.ping`. Liveness check; replies `pong`."""
        return await self._call("core.ping", {})

    async def session_get(self) -> Reply:
        """`session.get`. The whole object model; replies `session`."""
        return await self._call("session.get", {})

    async def window_create(self, *, cwd: str | None = None, workspace_name: str | None = None) -> Reply:
        """`window.create`. Opens a window with one empty workspace.

        workspace_name: Name of the window's first workspace.
        """
        return await self._call("window.create", {"cwd": cwd, "workspace_name": workspace_name})

    async def window_close(self, window: WindowId) -> Reply:
        """`window.close`. Closes a window and its workspaces, herdr workspaces included (see
        `workspace.close`).
        """
        return await self._call("window.close", {"window": window})

    async def window_focus(self, window: WindowId) -> Reply:
        """`window.focus`."""
        return await self._call("window.focus", {"window": window})

    async def window_set_frame(self, frame: Frame, window: WindowId) -> Reply:
        """`window.set_frame`. Records a window's frame after the user moves or resizes it."""
        return await self._call("window.set_frame", {"frame": frame, "window": window})

    async def window_set_sidebar(self, visible: bool, window: WindowId) -> Reply:
        """`window.set_sidebar`. Opens a window's workspace sidebar, or collapses it to a rail or out
        of sight, as `[sidebar] collapsed` says (restored on relaunch).

        visible: `true` opens the full sidebar; `false` collapses it (`[sidebar] collapsed`: a rail by default, or hidden).
        """
        return await self._call("window.set_sidebar", {"visible": visible, "window": window})

    async def window_list(self) -> Reply:
        """`window.list`. Every window; replies `windows`."""
        return await self._call("window.list", {})

    async def workspace_list(self, *, window: WindowId | None = None) -> Reply:
        """`workspace.list`. Workspaces of one window, or of all windows; replies `workspaces`.

        window: Only this window's workspaces; all when absent.
        """
        return await self._call("workspace.list", {"window": window})

    async def workspace_create(self, *, cwd: str | None = None, machine: str | None = None, name: str | None = None, window: WindowId | None = None) -> Reply:
        """`workspace.create`.

        machine: The herdr machine its terminals run on: `"local"` (the default), or a machine's ID or label from `machines.list`.
        window: Defaults to the focused window.
        """
        return await self._call("workspace.create", {"cwd": cwd, "machine": machine, "name": name, "window": window})

    async def workspace_close(self, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.close`. Closes a workspace and its tabs, and its herdr workspace with every
        tab and pane in it: their processes end. Closing a
        window's last workspace closes the window.

        workspace: Defaults to the focused workspace.
        """
        return await self._call("workspace.close", {"workspace": workspace})

    async def workspace_focus(self, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.focus`.

        workspace: Defaults to the focused workspace.
        """
        return await self._call("workspace.focus", {"workspace": workspace})

    async def workspace_rename(self, name: str, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.rename`. Renames a workspace, and its herdr workspace too."""
        return await self._call("workspace.rename", {"name": name, "workspace": workspace})

    async def workspace_set_repo(self, *, path: str | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.set_repo`. Sets the folder whose git branch the sidebar shows; without `path` the
        core follows the focused terminal's working directory again.

        path: A folder inside the repository; absent or empty follows the focused terminal again.
        workspace: Defaults to the focused workspace.
        """
        return await self._call("workspace.set_repo", {"path": path, "workspace": workspace})

    async def workspace_move(self, index: int, *, workspace: WorkspaceId | None = None) -> Reply:
        """`workspace.move`. Moves a workspace to another place in its window's list: the sidebar
        order, which ⌘1…⌘8 and ⌘9 (the last) follow. Saved with the session.
        It's Azulejo's own order: herdr's workspace order stays as it is.

        index: New position within its window, from 0, counted once the workspace has left its old place; past the end means last. A workspace stays in its machine's group (the window's list is grouped by machine, as the sidebar shows it), so a place past the group's edge stops there.
        """
        return await self._call("workspace.move", {"index": index, "workspace": workspace})

    async def workspace_bind(self, herdr_workspace: str, workspace: WorkspaceId) -> Reply:
        """`workspace.bind`. Records the herdr workspace backing a workspace. Sent by the herdr adapter."""
